                <p style={{ marginBottom: '0.5rem' }}>{post.content}</p>
                <small style={{ color: '#666' }}>
                  Created: {new Date(post.createdAt).toLocaleDateString()}
                </small>
              </article>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}

